#!/usr/bin/env python3
"""Contract checks for gorseford_routes.py. Do not edit this file to pass."""

from __future__ import annotations

import sys
import traceback

from gorseford_routes import RouteError, compile_routes


def _fail(name, detail):
    return (name, False, detail)


def _pass(name, detail="ok"):
    return (name, True, detail)


def test_methods_and_normalization():
    name = "methods are limited and paths are normalized"
    try:
        compile_routes(
            [{"name": "create", "method": "PUT", "path": "/notices"}]
        )
    except RouteError:
        put_rejected = True
    except Exception as exc:
        return _fail(name, f"PUT raised {type(exc).__name__}: {exc}")
    else:
        return _fail(name, "PUT was accepted")

    try:
        result = compile_routes(
            [
                {"name": "list", "method": "GET", "path": "trails/"},
                {"name": "root", "method": "GET", "path": "/"},
            ]
        )
    except Exception as exc:
        return _fail(name, f"valid routes raised {type(exc).__name__}: {exc}")

    paths = {item["name"]: item["path"] for item in result}
    if paths.get("list") != "/trails":
        return _fail(name, f"list path was {paths.get('list')!r}, expected '/trails'")
    if paths.get("root") != "/":
        return _fail(name, f"root path was {paths.get('root')!r}, expected '/'")
    return _pass(name)


def test_trailing_slash_is_the_same_route():
    name = "trailing slashes do not create a second route"
    try:
        compile_routes(
            [
                {"name": "a", "method": "GET", "path": "/notices"},
                {"name": "b", "method": "GET", "path": "/notices/"},
            ]
        )
    except RouteError:
        return _pass(name)
    except Exception as exc:
        return _fail(name, f"raised {type(exc).__name__}: {exc}")
    else:
        return _fail(name, "/notices and /notices/ were both accepted")


def test_static_and_param_conflict():
    name = "a static segment conflicts with a parameter in the same position"
    try:
        compile_routes(
            [
                {"name": "featured", "method": "GET", "path": "/trails/featured"},
                {"name": "one", "method": "GET", "path": "/trails/{id}"},
            ]
        )
    except RouteError:
        conflict_ok = True
    except Exception as exc:
        return _fail(name, f"conflict raised {type(exc).__name__}: {exc}")
    else:
        return _fail(name, "GET /trails/featured and GET /trails/{id} were both accepted")

    try:
        compile_routes(
            [
                {"name": "featured", "method": "GET", "path": "/trails/featured"},
                {"name": "update", "method": "PATCH", "path": "/trails/{id}"},
            ]
        )
    except Exception as exc:
        return _fail(name, f"different methods raised {type(exc).__name__}: {exc}")
    return _pass(name, "same-method conflict rejected; different methods allowed")


def test_param_names_and_healthz():
    name = "parameter names are identifiers and healthz is GET /healthz"
    try:
        compile_routes(
            [{"name": "bad", "method": "GET", "path": "/trails/{trail-id}"}]
        )
    except RouteError:
        hyphen_ok = True
    except Exception as exc:
        return _fail(name, f"hyphen param raised {type(exc).__name__}: {exc}")
    else:
        return _fail(name, "parameter name 'trail-id' was accepted")

    try:
        compile_routes(
            [{"name": "healthz", "method": "POST", "path": "/healthz"}]
        )
    except RouteError:
        health_ok = True
    except Exception as exc:
        return _fail(name, f"healthz raised {type(exc).__name__}: {exc}")
    else:
        return _fail(name, "POST /healthz was accepted for name healthz")

    try:
        result = compile_routes(
            [{"name": "healthz", "method": "GET", "path": "/healthz/"}]
        )
    except Exception as exc:
        return _fail(name, f"valid healthz raised {type(exc).__name__}: {exc}")
    if result[0]["path"] != "/healthz" or result[0]["method"] != "GET":
        return _fail(name, f"valid healthz compiled to {result[0]}")
    return _pass(name)


def test_sort_order():
    name = "compiled routes are sorted by path, then method"
    try:
        result = compile_routes(
            [
                {"name": "post_a", "method": "POST", "path": "/a"},
                {"name": "get_z", "method": "GET", "path": "/z"},
                {"name": "get_a", "method": "GET", "path": "/a"},
            ]
        )
    except Exception as exc:
        return _fail(name, f"raised {type(exc).__name__}: {exc}")
    order = [(item["method"], item["path"]) for item in result]
    expected = [("GET", "/a"), ("POST", "/a"), ("GET", "/z")]
    if order != expected:
        return _fail(name, f"order was {order}, expected {expected}")
    return _pass(name)


CHECKS = [
    test_methods_and_normalization,
    test_trailing_slash_is_the_same_route,
    test_static_and_param_conflict,
    test_param_names_and_healthz,
    test_sort_order,
]


def main():
    results = []
    for check in CHECKS:
        try:
            results.append(check())
        except Exception as exc:
            results.append(
                (
                    check.__name__,
                    False,
                    f"checker crashed: {type(exc).__name__}: {exc}\n{traceback.format_exc()}",
                )
            )

    width = max(len(name) for name, _, _ in results)
    failed = 0
    for name, ok, detail in results:
        status = "PASS" if ok else "FAIL"
        if not ok:
            failed += 1
        print(f"{status}  {name.ljust(width)}  {detail}")

    print()
    print(f"{len(results) - failed}/{len(results)} checks passed")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
